/*{
  "DESCRIPTION": "Gently falling snow made of soft drifting dots over a dark background",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "snowColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "skyColor", "TYPE": "color", "DEFAULT": [0.02, 0.02, 0.08, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 1.0, "MAX": 6.0, "DEFAULT": 3.0 },
    { "NAME": "flakeSize", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.2 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float flakeLayer(vec2 uv, float cells, float t, float seedOffset, float sizeMul) {
  vec2 guv = uv * cells;
  guv.x += sin(t * 0.5 + seedOffset) * 0.5;
  vec2 cellId = floor(guv);
  vec2 f = fract(guv);

  float best = 0.0;
  for (int i = -1; i <= 1; i++) {
    vec2 neighbor = vec2(float(i), 0.0);
    vec2 id = cellId + neighbor;
    float h = hash(id + seedOffset);
    float h2 = hash(id + seedOffset + 17.0);
    float drift = sin(t * 0.3 + h * 6.28) * 0.3;
    vec2 center = vec2(0.5 + drift, fract(h + t * 0.15 * (0.5 + h2)));
    vec2 diff = (f - neighbor) - center;
    diff.x *= 1.6;
    float d = length(diff);
    float r = flakeSize * sizeMul * (0.5 + h2 * 0.5);
    float flake = smoothstep(r, r * 0.2, d);
    best = max(best, flake);
  }
  return best;
}

void main() {
  vec2 uv = isf_FragNormCoord;
  float t = TIME * speed;

  bool isFlat = RENDERSIZE.y < 2.0;
  vec2 motionUV = uv;
  if (isFlat) {
    motionUV = vec2(uv.x, fract(uv.x * 3.0 + sin(TIME * 0.1) * 0.1));
  }

  float snow = 0.0;
  snow = max(snow, flakeLayer(motionUV, density, t * 1.0, 0.0, 1.0));
  snow = max(snow, flakeLayer(motionUV, density * 1.7, t * 1.6, 5.3, 0.6));
  snow = max(snow, flakeLayer(motionUV, density * 2.4, t * 2.2, 11.1, 0.4));

  vec3 col = mix(skyColor.rgb, snowColor.rgb, snow);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Flickering fire rising from the bottom of the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.8, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 8.0, "DEFAULT": 3.0 },
    { "NAME": "intensity", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.7 }
  ]
}*/

float hash(float n) {
  return fract(sin(n * 127.1) * 43758.5453);
}

float noise1(float x) {
  float i = floor(x);
  float f = fract(x);
  float a = hash(i);
  float b = hash(i + 1.0);
  return mix(a, b, smoothstep(0.0, 1.0, f));
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool isRoofline = RENDERSIZE.y < 2.0;

  float t = TIME * speed;

  // rising coordinate: normally y goes up, but if flat, use x instead
  float rise = isRoofline ? uv.x : uv.y;
  float across = isRoofline ? 0.5 : uv.x;

  // flame flicker noise, moving upward over time
  float n1 = noise1(across * scale * 6.0 + t * 3.0 - rise * 8.0);
  float n2 = noise1(across * scale * 12.0 - t * 5.0 - rise * 14.0 + 5.0);
  float flicker = n1 * 0.6 + n2 * 0.4;

  // base heat falls off toward the top, boosted by flicker and intensity
  float heat = (1.0 - rise) * (0.6 + 0.4 * flicker) + flicker * intensity * 0.5;
  heat = clamp(heat, 0.0, 1.0);

  // sharpen so the fire has a defined body with a flickering tip
  float body = smoothstep(0.15, 0.9, heat);

  vec3 col = mix(colorB.rgb * 0.3, colorA.rgb, body);
  col = mix(colorB.rgb, col, smoothstep(0.0, 0.35, heat));

  // slight overall pulsing brightness for extra life
  float pulse = 0.9 + 0.1 * sin(t * 6.0 + across * 20.0);
  col *= pulse;

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

/*{
  "DESCRIPTION": "Diagonal scrolling candy cane stripes in two colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 12.0, "DEFAULT": 5.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.01, "MAX": 0.5, "DEFAULT": 0.1 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float diag;
  if (RENDERSIZE.y < 2.0) {
    diag = uv.x;
  } else {
    diag = uv.x + uv.y;
  }

  float stripes = diag * scale - TIME * speed;
  float band = fract(stripes);

  float edge = clamp(sharpness, 0.01, 0.5);
  float mask = smoothstep(0.5 - edge, 0.5 + edge, band);

  vec3 col = mix(colorA.rgb, colorB.rgb, mask);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A smooth wash that fades slowly between the chosen colours",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 1.0 }
  ]
}*/
void main() {
  float t = TIME * speed * 0.15;

  float cycle = fract(t);
  float seg = cycle * 3.0;
  float idx = floor(seg);
  float localT = fract(seg);

  float blendWidth = max(softness, 0.001);
  float mixAmt = smoothstep(0.0, blendWidth, localT);

  vec3 colA = mix(colorA.rgb, colorB.rgb, step(1.0, idx + 0.0) * 0.0 + step(0.5, idx) * 0.0);
  vec3 fromColor = mix(colorA.rgb, mix(colorB.rgb, colorC.rgb, step(1.5, idx)), step(0.5, idx));
  vec3 toColor = mix(colorB.rgb, mix(colorC.rgb, colorA.rgb, step(1.5, idx)), step(0.5, idx));

  vec3 washColor = mix(fromColor, toColor, mixAmt);

  gl_FragColor = vec4(washColor, 1.0);
}

/*{
  "DESCRIPTION": "Twinkling stars sparkle across the display in shifting colours",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 34.23);
  return fract(p.x * p.y);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  // On tall/short displays, keep the star field two-dimensional in feel,
  // but if it's a 1-pixel-tall roofline, spread cells along x only.
  vec2 cellCoord;
  if (RENDERSIZE.y < 2.0) {
    cellCoord = vec2(uv.x * density * 2.0, 0.0);
  } else {
    cellCoord = uv * vec2(density, density * (RENDERSIZE.y / max(RENDERSIZE.x, 1.0)) * 2.0 + 1.0);
  }

  vec2 cell = floor(cellCoord);

  float starSeed = hash(cell);

  // Only some cells host a star
  float present = step(0.55, starSeed);

  // Each star twinkles on its own phase and rate
  float phase = hash(cell + 7.7) * 6.2831853;
  float rate = 0.6 + hash(cell + 3.3) * 1.4;
  float twinkle = 0.5 + 0.5 * sin(TIME * speed * rate + phase);

  // Sharpen the twinkle so stars mostly sit dim/off with bright flashes
  float bright = pow(twinkle, mix(1.0, 8.0, sharpness));

  float starVal = present * bright;

  // Colour drifts per-star between colorA and colorB
  float colorMix = hash(cell + 1.1);
  vec3 starColor = mix(colorA.rgb, colorB.rgb, colorMix);

  vec3 col = starColor * starVal;

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Colored dots chase steadily along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "count", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.2 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // Always chase along x so it reads correctly on a thin roofline (y constant).
  float pos = uv.x;
  if (RENDERSIZE.y >= 2.0) {
    // For taller canvases, still favor horizontal motion but blend in a touch of y
    // so the chase reads on non-roofline shapes too, without breaking 1px-tall cases.
    pos = uv.x;
  }

  float n = max(count, 1.0);
  float scaled = pos * n - TIME * speed * 2.0;
  float cellPos = fract(scaled);
  float cellIndex = floor(scaled);

  // Distance from center of each cell, 0 at center, 0.5 at edge
  float d = abs(cellPos - 0.5);
  float dot = 1.0 - smoothstep(sharpness * 0.5, sharpness, d);

  // Cycle through three colors based on which light in the chase this is
  float colorPhase = mod(cellIndex, 3.0);
  vec3 col;
  if (colorPhase < 1.0) {
    col = colorA.rgb;
  } else if (colorPhase < 2.0) {
    col = colorB.rgb;
  } else {
    col = colorC.rgb;
  }

  // Dim background so unlit gaps are not fully black between chase lights
  vec3 background = vec3(0.03, 0.02, 0.02);
  vec3 finalColor = mix(background, col, dot);

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma blend of three Christmas colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.0 }
  ]
}*/
void main() {
  bool isLine = RENDERSIZE.y < 2.0;
  vec2 uv = isf_FragNormCoord * 2.0 - 1.0;
  uv.x *= scale;
  uv.y *= isLine ? 1.0 : scale;

  float t = TIME * speed;

  float x = isLine ? uv.x : uv.x;
  float y = isLine ? uv.x * 0.7 + 0.3 : uv.y;

  float p1 = sin(x * 1.7 + t);
  float p2 = sin((x * 0.6 + y * 1.3) * 1.3 - t * 1.3);
  float ang = atan(y, x);
  float rad = sqrt(x * x + y * y + 0.0001);
  float p3 = sin(rad * 3.0 - t * 1.7 + ang * 2.0);

  float plasma = (p1 + p2 + p3) / 3.0;
  plasma = plasma * 0.5 + 0.5;

  float band = plasma * 2.0;
  vec3 col;
  if (band < 1.0) {
    col = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 1.0, band));
  } else {
    col = mix(colorB.rgb, colorC.rgb, smoothstep(0.0, 1.0, band - 1.0));
  }

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A rainbow of color bands sweeps across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.6 },
    { "NAME": "brightness", "TYPE": "float", "MIN": 0.2, "MAX": 1.0, "DEFAULT": 1.0 }
  ]
}*/

vec3 rainbow(float t) {
  float h = fract(t);
  vec3 c = clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  c = c * c * (3.0 - 2.0 * c);
  return c;
}

void main() {
  vec2 uv = isf_FragNormCoord;
  float pos = RENDERSIZE.y < 2.0 ? uv.x : (uv.x + uv.y * 0.35);
  float t = pos * scale - TIME * speed * 0.5;

  vec3 col = rainbow(t);

  float bandCount = mix(1.0, 6.0, sharpness);
  float banded = floor(fract(t) * bandCount) / bandCount;
  vec3 colHard = rainbow(banded + t - fract(t));
  col = mix(col, colHard, sharpness);

  col *= brightness;

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

/*{
  "DESCRIPTION": "Everything pulses in bright bands to a steady beat",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.8, 0.2, 1.0] },
    { "NAME": "bpm", "TYPE": "float", "MIN": 40.0, "MAX": 200.0, "DEFAULT": 120.0 },
    { "NAME": "bands", "TYPE": "float", "MIN": 1.0, "MAX": 8.0, "DEFAULT": 3.0 },
    { "NAME": "punch", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float beatsPerSec = bpm / 60.0;
  float phase = fract(TIME * beatsPerSec);

  float pulse = pow(1.0 - phase, 3.0 + punch * 5.0);
  pulse = clamp(pulse, 0.0, 1.0);

  float axis = (RENDERSIZE.y < 2.0) ? uv.x : uv.x;
  float bandPos = fract(axis * bands);
  float bandShape = step(0.5, bandPos);

  vec3 base = mix(colorA.rgb, colorB.rgb, bandShape);

  float glow = mix(0.35, 1.0, pulse);
  vec3 col = base * glow;

  col += vec3(pulse * 0.25);

  col = clamp(col, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A waving American flag of red white and blue stripes with a blue star field corner",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.8, 0.05, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.05, 0.1, 0.6, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "waveAmount", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool thin = RENDERSIZE.y < 2.0;

  // Use px as the coordinate that runs along the flag's long axis (waving direction)
  // and py as the short axis. On a 1-pixel-tall roofline, fake the wave along x.
  float px = thin ? uv.x : uv.x;
  float py = thin ? 0.5 : uv.y;

  float t = TIME * speed;

  // Waving displacement: ripples travel along x, displace the stripe pattern in y
  float wave = sin(px * 10.0 + t * 3.0) * 0.03 * waveAmount
             + sin(px * 4.0 + t * 1.7) * 0.02 * waveAmount;

  float wavedY = py + wave;

  vec3 col;

  if (thin) {
    // Roofline: represent the flag as a horizontal sequence -
    // canton (stars, blue) on the left, stripes waving along the rest via brightness pulses
    float cantonWidth = 0.35;
    if (px < cantonWidth) {
      // star field flicker along x
      float starPulse = step(0.5, fract(px * 14.0 + sin(t * 2.0) * 0.5));
      col = mix(colorC.rgb, colorB.rgb, starPulse * 0.5);
    } else {
      float stripeCoord = (px - cantonWidth) * 13.0 + wave * 8.0;
      float stripeBand = step(0.5, fract(stripeCoord));
      col = mix(colorA.rgb, colorB.rgb, stripeBand);
    }
  } else {
    float cantonWidth = 0.4;
    float cantonHeight = 0.55;

    if (px < cantonWidth && py > (1.0 - cantonHeight) + wave * 0.5) {
      // Star field: small grid of stars on blue
      vec2 starUV = vec2(px / cantonWidth, (py - (1.0 - cantonHeight)) / cantonHeight);
      vec2 grid = fract(starUV * vec2(6.0, 5.0)) - 0.5;
      float starDot = 1.0 - smoothstep(0.08, 0.18, length(grid));
      col = mix(colorC.rgb, colorB.rgb, starDot);
    } else {
      // Stripes: 13 stripes alternating red/white, waved in y
      float stripeIndex = floor(wavedY * 13.0);
      float stripeBand = mod(stripeIndex, 2.0);
      float band = step(0.5, stripeBand);
      col = mix(colorB.rgb, colorA.rgb, band);
    }
  }

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 0.15, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.1, 0.8, 0.2, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.0 },
    { "NAME": "murk", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float total = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    total += noise(p) * amp;
    p *= 2.0;
    amp *= 0.5;
  }
  return total;
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;

  float t = TIME * speed * 0.15;

  vec2 p = uv * scale;
  if (isLine) {
    p = vec2(uv.x * scale * 2.0, 0.5);
  }

  vec2 driftA = vec2(t, isLine ? 0.0 : t * 0.35);
  vec2 driftB = vec2(-t * 0.6, isLine ? 0.0 : t * 0.2);

  float f1 = fbm(p + driftA);
  float f2 = fbm(p * 1.7 - driftB + 4.2);
  float fog = f1 * 0.6 + f2 * 0.4;

  fog = smoothstep(0.2, 0.85, fog);
  fog = mix(fog, fog * fog, murk);

  float glow = 0.5 + 0.5 * sin(t * 2.0 + f1 * 6.28318);
  fog = clamp(fog + glow * 0.05, 0.0, 1.0);

  vec3 col = mix(colorA.rgb, colorB.rgb, fog);
  col = max(col, colorA.rgb * 0.4);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Spinning concentric tunnel rings that fly toward the viewer",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "rings", "TYPE": "float", "MIN": 1.0, "MAX": 12.0, "DEFAULT": 6.0 },
    { "NAME": "spin", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  if (RENDERSIZE.y < 2.0) {
    // roofline fallback: fly-through becomes motion along x
    float x = fract(uv.x - TIME * speed * 0.3);
    float ring = fract(x * rings);
    float band = step(ring, 0.5);
    vec3 col = mix(colorA.rgb, colorB.rgb, band);
